# Sesión 6: permisos, otra persona, efectivo, registro de chofer en 7 pasos, deslizar, validar efectivo, calificar pasajeros, niveles.
import asyncio, os
from playwright.async_api import async_playwright
BASE = "http://localhost:5180"
OUT = "capturas/sesion-6"
os.makedirs(OUT, exist_ok=True)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 390, "height": 844}, device_scale_factor=2)
        errores = []
        pg.on("console", lambda m: errores.append(m.text) if m.type == "error" else None)
        pg.on("pageerror", lambda e: errores.append(str(e)))
        async def foto(n):
            await pg.wait_for_timeout(500)
            await pg.screenshot(path=f"{OUT}/{n}.png", full_page=True); print("foto", n)
        async def desliza():
            el = await pg.query_selector(".deslizar .perilla-d"); await el.scroll_into_view_if_needed(); await pg.wait_for_timeout(150)
            box = await el.bounding_box()
            pista = await (await pg.query_selector(".deslizar")).bounding_box()
            x0, y0 = box["x"] + box["width"] / 2, box["y"] + box["height"] / 2
            await pg.mouse.move(x0, y0); await pg.mouse.down()
            for i in range(1, 11): await pg.mouse.move(x0 + (pista["width"] - 70) * i / 10, y0); await pg.wait_for_timeout(20)
            await pg.mouse.up(); await pg.wait_for_timeout(400)
        await pg.goto(BASE + "/#/inicio"); await pg.evaluate("localStorage.clear()"); await pg.reload()
        await pg.wait_for_selector("text=¿Cómo entras hoy?")
        await pg.add_style_tag(content=".pie{position:static !important} .tabs{position:static !important} .flotantes{position:static !important}")
        # ---- crear cuenta con género y ciudad → permisos
        await pg.click("text=Crear cuenta"); await pg.fill("input[placeholder='Como en tu cédula']", "Raúl Rodríguez")
        await pg.fill("input[type=email]", "raul@xpuesto.app"); await pg.fill("input[type=password]", "1234")
        await pg.fill("input[placeholder='V-12345678']", "V-14.523.998"); await pg.fill("input[placeholder='0414-1234567']", "0414-5551234")
        await pg.select_option("label:has-text('Género') select", "Masculino"); await pg.select_option("label:has-text('Ciudad') select", "Caracas")
        await foto("1-crear-cuenta")
        await pg.click("text=Crear mi cuenta de pasajero"); await pg.wait_for_selector("text=Permisos de la app"); await foto("2-permisos")
        await pg.click("text=Permitir todo"); await pg.click("text=Listo, seguir"); await pg.wait_for_selector("text=¿Pa' dónde vas, Raúl?")
        # ---- detalle: favorito + otra persona; confirmar en efectivo
        await pg.click("text=Buscar salidas"); await pg.click("text=José R. >> nth=0"); await pg.wait_for_selector("text=Elige tus puestos")
        await pg.click("button[aria-label='Chofer favorito']")
        await pg.evaluate("document.querySelectorAll('.carro g')[1].dispatchEvent(new MouseEvent('click',{bubbles:true}))")
        await pg.click("text=Viaja otra persona, no yo"); await pg.fill("input[placeholder='Quién viaja']", "Mamá"); await pg.fill("input[placeholder='0414-1234567']", "0412-9876543")
        await foto("3-detalle-favorito-otra-persona")
        await pg.click("text=Seguir con"); await pg.click("text=Bolso de mano"); await pg.click("text=Revisar mi reserva"); await pg.wait_for_selector("text=¿Cómo pagas?")
        await pg.click("text=Efectivo al chofer"); await foto("4-confirmar-efectivo")
        await pg.click("text=Confirmar reserva"); await pg.wait_for_selector("text=Ver mi viaje"); await foto("5-listo-efectivo")
        await pg.goto(BASE + "/#/perfil"); await pg.wait_for_selector("text=Próximo viaje"); await foto("6-perfil-proximo-favoritos")
        # ---- registro de chofer, 7 pasos
        await pg.click("text=Quiero manejar con XPuesto"); await pg.wait_for_selector("text=Registro de chofer")
        await pg.fill("label:has-text('Apellido') input", "Rodríguez"); await pg.fill("label:has-text('Nacimiento') input", "1988-05-12")
        await pg.select_option("label:has-text('Género') select", "Masculino")
        await pg.select_option("label:has-text('Ciudad') select", "Caracas"); await pg.fill("input[placeholder='Chacao'] >> nth=0", "Chacao"); await pg.fill("input[placeholder='Chacao'] >> nth=1", "Chacao")
        await pg.select_option("label:has-text('Banco') select", "Mercantil"); await pg.fill("input[placeholder='0105-0000-00-0000000000']", "0105-0123-45-1234567890")
        await foto("7-chofer-datos"); await pg.click("text=Siguiente"); await pg.wait_for_selector("text=Documentos")
        await pg.click("text=Tu foto, fondo blanco")
        await pg.fill("input[placeholder='V-12345678']", "V-14523998")
        for inp in await pg.query_selector_all("input[type=date]"): await inp.fill("2028-05-05")
        for i in range(3): await pg.click(".doc-bloque .doc-fila:not(.ok) >> nth=0"); await pg.wait_for_timeout(120)
        await foto("8-chofer-documentos"); await pg.click("text=Siguiente"); await pg.wait_for_selector("text=Tu carro")
        await pg.select_option("label:has-text('Marca') select", "Toyota"); await pg.fill("input[placeholder='Corolla']", "Corolla")
        await pg.select_option("label:has-text('Año') select", "2019"); await pg.select_option("label:has-text('Color') select", "Azul"); await pg.fill("input[placeholder='AB123CD']", "AB123CD")
        await pg.select_option("label:has-text('Caja') select", "Sincrónico"); await pg.select_option("label:has-text('Capacidad de peso') select", "Hasta 500 kg")
        await pg.fill("input[placeholder='12345678']", "45678901"); await pg.fill("input[placeholder='ABC123456']", "XYZ987654"); await pg.click("text=Foto del carnet")
        await foto("9-chofer-carro"); await pg.click("text=Siguiente"); await pg.wait_for_selector("text=Inspección virtual")
        for i in range(8): await pg.click(".foto-carro:not(.ok) >> nth=0"); await pg.wait_for_timeout(100)
        await pg.click("text=Evaluar las fotos"); await pg.wait_for_selector("text=Aprobada con observaciones"); await foto("10-chofer-virtual")
        await pg.click("text=Siguiente"); await pg.wait_for_selector("text=Inspección presencial y entrevista")
        await pg.select_option("label:has-text('Sede') select", "Caracas · La Castellana"); await pg.click("text=Jue 24 · 9:00 am")
        resp = ["No, nunca. Si tomé, no manejo y aviso que no puedo salir.", "Mantengo la calma, le explico la situación y busco una ruta alterna con paciencia.", "Me bajo, le ayudo a cargar las maletas y las subo al maletero con cuidado.", "Lo escucho completo, me disculpo si corresponde y lo reporto al soporte de XPuesto."]
        areas = await pg.query_selector_all("textarea")
        for a, t in zip(areas, resp): await a.fill(t)
        await pg.click("text=Evaluar mis respuestas"); await pg.wait_for_selector("text=Aprobada"); await foto("11-chofer-entrevista")
        await pg.click("text=Siguiente"); await pg.wait_for_selector("text=Inducción"); await pg.click(".video"); await foto("12-chofer-induccion")
        await pg.click("text=Siguiente"); await pg.wait_for_selector("text=Activar tu cuenta")
        await pg.fill("input[type=date]", "2027-10-30"); await pg.click(".perilla.grande"); await foto("13-chofer-activar")
        await pg.click("text=Enviar mi registro"); await pg.wait_for_selector("text=En revisión"); await foto("14-chofer-en-revision")
        await pg.click("button:has-text(\"Simular aprobación\")"); await pg.wait_for_selector("text=¡Aprobado!")
        await pg.click("text=Entrar a mi app de chofer"); await pg.wait_for_selector("text=Hola, Raúl"); await foto("15-chofer-hoy-nivel")
        await pg.goto(BASE + "/#/conductor/perfil"); await pg.wait_for_selector("text=Tu nivel"); await foto("16-perfil-chofer-niveles")
        # ---- salida activa: deslizar, validar efectivo, calificar
        await pg.goto(BASE + "/#/conductor/salida"); await pg.wait_for_selector("text=Salida en 40 min"); await foto("17-salida-deslizar")
        await desliza(); await pg.wait_for_selector("text=Vas a la parada"); await desliza(); await pg.wait_for_selector("text=Estás en la parada")
        await pg.click("text=Tomar la foto")
        for i in range(3): await pg.click("text=Abordó >> nth=0"); await pg.wait_for_timeout(120)
        await pg.click("text=Validar efectivo"); await pg.wait_for_selector("text=Validar efectivo · Raúl S."); await pg.click("text=$20"); await foto("18-validar-efectivo")
        await pg.click("text=Confirmar $20 recibidos"); await pg.wait_for_timeout(300); await foto("19-parada-efectivo-ok")
        await desliza(); await pg.wait_for_selector("text=En ruta a Valencia"); await pg.wait_for_timeout(9500); await desliza(); await pg.wait_for_selector("text=Viaje terminado")
        for i in range(3): await pg.click(f".estrellas-fila >> nth={i} >> button >> nth=4")
        await foto("20-calificar-pasajeros-liquidacion")
        await pg.click("text=Enviar y cobrar"); await pg.wait_for_selector("text=Fondo para vueltos"); await foto("21-billetera")
        await b.close()
        print("errores de consola:", errores if errores else "ninguno")
asyncio.run(main())
